import{_ as n,o as a,c as s,ag as p}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"从 Prompt 到 Graph：Agent 的五层能力演进","description":"","frontmatter":{},"headers":[],"relativePath":"AI/prompt-to-graph.md","filePath":"AI/prompt-to-graph.md"}'),r={name:"AI/prompt-to-graph.md"};function o(e,t,l,i,d,g){return a(),s("div",null,[...t[0]||(t[0]=[p(`<h1 id="从-prompt-到-graph-agent-的五层能力演进" tabindex="-1">从 Prompt 到 Graph：Agent 的五层能力演进 <a class="header-anchor" href="#从-prompt-到-graph-agent-的五层能力演进" aria-label="Permalink to &quot;从 Prompt 到 Graph：Agent 的五层能力演进&quot;">​</a></h1><p>做 AI 应用时，很多人一上来就堆 Prompt，或直接冲向「多智能体」。更稳妥的看法是：能力是<strong>一层层叠上去</strong>的——</p><blockquote><p><strong>Prompt → Context → Harness → Loop → Graph</strong></p></blockquote><p>它们不是互相替代的产品名，而是同一条能力演进线上的五个台阶：先让模型「听得懂」，再让它「看得到」，再「可控地动手」，再「多步推进」，最后才是「多节点编排」。</p><p>编码 Agent（Cursor、Claude Code 等）也走同一条线；下文例子以<strong>客服、研报、业务自动化</strong>为主，编码只作辅证。和「Agent 是什么」的关系见：<a href="./agent.html">Agent 概念</a>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Prompt   指令与角色</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Context  知识与状态</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Harness  工具、权限、校验</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Loop     思考 → 行动 → 观察</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Graph    多节点分支 / 并行 / 审批</span></span></code></pre></div><h2 id="prompt-先把话说清楚" tabindex="-1">Prompt：先把话说清楚 <a class="header-anchor" href="#prompt-先把话说清楚" aria-label="Permalink to &quot;Prompt：先把话说清楚&quot;">​</a></h2><p><strong>Prompt</strong> 是对模型的直接指令：角色、目标、输出格式、禁止事项。</p><p>例子：</p><ul><li>客服：「你是售后助手，只根据知识库回答；不确定就转人工。」</li><li>研报：「根据下方材料写 800 字摘要，分：结论 / 证据 / 风险。」</li></ul><p>这一层解决的是：<strong>意图对齐</strong>。写得好，单轮质量会明显上去。</p><p>局限也很清楚：</p><ul><li>没有业务事实（库存、订单、最新公告）时只能猜</li><li>不能查库、发邮件、改工单</li><li>多轮里容易「忘了刚才约定」——除非你把约定反复塞进下一轮</li></ul><p>实践要点：角色、边界、输出模板写死；把「不要做什么」写清楚，比堆形容词更有用。</p><h2 id="context-把该看的东西放进视野" tabindex="-1">Context：把该看的东西放进视野 <a class="header-anchor" href="#context-把该看的东西放进视野" aria-label="Permalink to &quot;Context：把该看的东西放进视野&quot;">​</a></h2><p>当「只会说话」不够时，需要 <strong>Context</strong>：在调用模型前，把相关信息注入上下文。</p><p>常见来源：</p><table tabindex="0"><thead><tr><th>类型</th><th>例子</th></tr></thead><tbody><tr><td>检索（RAG）</td><td>客服知识库、产品 FAQ、政策条文</td></tr><tr><td>会话状态</td><td>当前工单号、用户已选套餐、上一轮结论</td></tr><tr><td>业务快照</td><td>CRM 档案、订单状态、库存数字</td></tr><tr><td>结构化附件</td><td>表格、JSON、合同摘要</td></tr></tbody></table><p>客服场景：用户问「我的退款到哪了？」——仅靠 Prompt 不够，要把订单状态、退款规则、历史沟通摘要放进 Context，回答才站得住。</p><p>研报场景：把招股书章节、财报关键指标、近期公告检索结果塞进上下文，再要求按模板输出。</p><p>注意：Context <strong>不是越多越好</strong>。噪声多了，模型会抓错重点。实践上更关心：</p><ul><li>检索是否命中、是否过期</li><li>是否做了去重与截断</li><li>关键权限数据是否该进模型视野</li></ul><p>一句话：<strong>Prompt 管怎么说，Context 管看见什么。</strong></p><h2 id="harness-让「能说」变成「可控地做事」" tabindex="-1">Harness：让「能说」变成「可控地做事」 <a class="header-anchor" href="#harness-让「能说」变成「可控地做事」" aria-label="Permalink to &quot;Harness：让「能说」变成「可控地做事」&quot;">​</a></h2><p>有了指令和资料，下一步往往是接工具：查工单、调 CRM、发通知、写文档。真正难的不是「接上 API」，而是 <strong>Harness（运行时护栏）</strong>——约束 Agent <strong>可以动什么、怎么动、动坏了怎么办</strong>。</p><p>Harness 通常包括：</p><ul><li><strong>工具边界</strong>：能查哪些接口、能不能写、写前是否二次确认</li><li><strong>权限与审计</strong>：谁以什么身份调用；关键操作留痕</li><li><strong>格式与契约</strong>：工具入参校验、返回结构校验，失败要可读</li><li><strong>配额与超时</strong>：单次调用上限、重试次数、总耗时预算</li><li><strong>安全策略</strong>：脱敏、禁止外泄字段、危险动作黑名单</li></ul><p>客服自动化例子：允许「查询订单 / 发起退款申请」，但「直接打款」必须人工点确认——这就是 Harness，而不是再写一句「请谨慎」的 Prompt。</p><p>和现有概念的对应（编码场景更明显，通用场景同理）：</p><table tabindex="0"><thead><tr><th>概念</th><th>更偏哪一层</th></tr></thead><tbody><tr><td><a href="./skill.html">Skill</a></td><td>流程与规范（常挂在 Loop / Harness 上）</td></tr><tr><td><a href="./mcp.html">MCP</a></td><td>外部工具与数据通道（Harness 的「手脚」）</td></tr><tr><td>Agent 运行时</td><td>把 Prompt/Context/工具/循环装在一起的壳</td></tr></tbody></table><p>细节对比见：<a href="./skill-vs-mcp.html">Skill 与 MCP 异同</a>。</p><h2 id="loop-多步推进直到结束" tabindex="-1">Loop：多步推进直到结束 <a class="header-anchor" href="#loop-多步推进直到结束" aria-label="Permalink to &quot;Loop：多步推进直到结束&quot;">​</a></h2><p>单次「读 Context → 调一次工具 → 出答案」往往不够。复杂任务需要 <strong>Loop</strong>：在结束条件满足前，反复 <strong>思考 → 行动 → 观察</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标进入</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>[思考] 下一步做什么？</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>[行动] 调工具 / 写中间结果 / 问人</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>[观察] 结果或报错</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>完成？──否──→ 回到思考</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>  是</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>交付结论</span></span></code></pre></div><p>这就是常见的 ReAct 形态，也是 <a href="./agent.html">Agent</a> 的核心循环。</p><p>自动化例子：夜间对账——拉账单 → 比对差异 → 分类异常 → 生成报告 → 超阈值则建工单。每一步依赖上一步观察结果，靠 Loop 串起来。</p><p>实践检查点：</p><ul><li><strong>结束条件</strong>写清：成功标准是什么，何时放弃</li><li><strong>步数 / 超时上限</strong>：防止空转烧钱</li><li><strong>失败回退</strong>：换策略、降级、转人工，而不是无限重试</li><li><strong>中间状态可观测</strong>：方便排障与审计</li></ul><p>Loop 解决的是「一件事要走很多步」；还没解决「很多种路径、多个角色怎么协作」。</p><h2 id="graph-从单环到多节点编排" tabindex="-1">Graph：从单环到多节点编排 <a class="header-anchor" href="#graph-从单环到多节点编排" aria-label="Permalink to &quot;Graph：从单环到多节点编排&quot;">​</a></h2><p>当流程出现分支、并行、多人（或多 Agent）分工时，单 Loop 会变臃肿。这时升到 <strong>Graph</strong>：把任务拆成节点，用边表达依赖与路由。</p><p>研报流水线示意：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>          ┌─→ [检索公告] ─┐</span></span>
<span class="line"><span>[选题] ───┼─→ [拉财报]   ─┼─→ [分析撰写] → [合规审校] → [人工签发]</span></span>
<span class="line"><span>          └─→ [竞品对比] ─┘</span></span></code></pre></div><p>典型能力：</p><ul><li><strong>分支</strong>：投诉类型不同，走退款 / 换货 / 技术排查不同子图</li><li><strong>并行</strong>：检索、拉数、竞品可同时跑，再汇总</li><li><strong>人工节点</strong>：高风险步骤插入审批闸门</li><li><strong>多角色</strong>：研究员 Agent、风控 Agent、编辑 Agent 各守一段</li></ul><p>客服升级例子：L1 机器人 Loop 解不了 → 路由到「退款子图」或「技术排障子图」→ 仍失败则进人工队列。这是 Graph 路由，而不是把所有 if/else 塞进一个超长 Prompt。</p><p>注意：Graph 成本更高（编排、状态机、可观测性、测试）。多数业务先把 <strong>Prompt + Context + Harness + 单 Loop</strong> 做稳，再按真实分支复杂度上图。</p><h2 id="总对照表" tabindex="-1">总对照表 <a class="header-anchor" href="#总对照表" aria-label="Permalink to &quot;总对照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>解决什么</th><th>缺它时的症状</th><th>实践检查点</th></tr></thead><tbody><tr><td><strong>Prompt</strong></td><td>意图、角色、输出格式</td><td>答非所问、格式乱、越界胡说</td><td>边界与模板是否写死</td></tr><tr><td><strong>Context</strong></td><td>看见事实与状态</td><td>瞎编业务细节、答非最新政策</td><td>检索质量、截断、权限</td></tr><tr><td><strong>Harness</strong></td><td>可控地调用工具</td><td>乱调 API、无审计、一次写挂生产</td><td>权限、校验、超时、确认</td></tr><tr><td><strong>Loop</strong></td><td>多步完成单一目标</td><td>一步做不完、不会根据结果调整</td><td>结束条件、步数上限、回退</td></tr><tr><td><strong>Graph</strong></td><td>分支 / 并行 / 多角色协作</td><td>单环里塞满 if、难以维护与扩容</td><td>节点边界、人工闸门、可观测</td></tr></tbody></table><p>选型口诀：<strong>能用下一层解决的问题，不要急着跳两层。</strong> 客服 FAQ 可能到 Context 就够；对账自动化要 Loop；跨部门研报签发才值得 Graph。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五层是<strong>能力叠层</strong>，不是五个互斥产品</li><li><strong>Prompt</strong> 对齐说法，<strong>Context</strong> 对齐事实，<strong>Harness</strong> 对齐安全与工具，<strong>Loop</strong> 对齐多步执行，<strong>Graph</strong> 对齐复杂编排</li><li>落地时先问：卡在「不会说」「看不见」「不敢动」「走不完」「路径太乱」的哪一层</li><li>Agent / Skill / MCP 是工程上的组装方式；可以分别挂在 Harness 与 Loop 上，详见 <a href="./agent.html">Agent</a>、<a href="./skill.html">Skill</a>、<a href="./mcp.html">MCP</a></li></ul><p>下一步建议：挑一个真实业务流，标出当前停在第几层，再只升一层做验证——比一上来画多智能体图更省时间。</p>`,53)])])}const m=n(r,[["render",o]]);export{c as __pageData,m as default};
